    """
    Checks whether the given number can be represented as the sum of non-zero powers of 2.

    Args:
        n (int): The number to check.

    Returns:
        bool: True if the number can be represented as the sum of non-zero powers of 2, False otherwise.
    """
    def is_power_of_two(i):
        return (i & (i - 1) == 0) and i != 0

    powers_of_two = [i for i in range(1, n + 1) if is_power_of_two(i)]
    for i in range(1, n + 1):
        dp = [False] * (n + 1)
        dp[0] = True
        for power in powers_of_two:
            if i >= power:
                for j in range(power, n + 1):
                    if j <= i and dp[i - j] and (j not in powers_of_two or j >= i):
                        dp[i] = True
    return dp[n] and n != 0
```

