    This function calculates the sum of digits of each number in a list.

    Parameters:
    numbers (list): A list that can contain integers, negative integers and/or other numbers.

    Returns:
    int: The sum of digits of each number in the list.
    """
    def sum_digits(num):
        # Check if the input is a list
        if isinstance(num, list):
            # Sum of digits for each number in the list
            return sum(sum_digits(n) for n in num)
        # Check if input is a string
        elif isinstance(num, str):
            return sum(int(digit) for digit in str(abs(num)) if digit.isdigit())
        else:
            # Convert the number to string, filter out non-digit characters, 
            # convert the string back to a list of integers, and sum them up.
            return sum(int(digit) for digit in str(abs(num)) if digit.isdigit())

    return sum(sum_digits(num) for num in numbers)
